class Solution {
public:
    int countKSubsequencesWithMaxBeauty(string s, int k) {
        long long mod = 1e9 + 7;
        vector<int> cnt(26, 0);
        for (char c : s) cnt[c - 'a']++;
        vector<int> freqs;
        for (int f : cnt) if (f > 0) freqs.push_back(f);
        if (freqs.size() < k) return 0;
        sort(freqs.rbegin(), freqs.rend());
        int cutoff = freqs[k - 1];
        long long ans = 1;
        int strictly_greater = 0, total_cutoff = 0;
        for (int f : freqs) {
            if (f > cutoff) {
                ans = (ans * f) % mod;
                strictly_greater++;
            } else if (f == cutoff) {
                total_cutoff++;
            }
        }
        int needed = k - strictly_greater;
        auto comb = [&](int n, int r) -> long long {
            if (r < 0 || r > n) return 0;
            long long res = 1;
            for (int i = 1; i <= r; i++) {
                res = res * (n - i + 1) / i;
            }
            return res % mod;
        };
        long long ways = comb(total_cutoff, needed);
        ans = (ans * ways) % mod;
        auto power = [&](long long base, long long exp) -> long long {
            long long res = 1;
            base %= mod;
            while (exp > 0) {
                if (exp % 2 == 1) res = (res * base) % mod;
                base = (base * base) % mod;
                exp /= 2;
            }
            return res;
        };
        ans = (ans * power(cutoff, needed)) % mod;
        return ans;
    }
};

class Solution {
    public int countKSubsequencesWithMaxBeauty(String s, int k) {
        long mod = 1_000_000_007L;
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        List<Integer> freqs = new ArrayList<>();
        for (int f : cnt) if (f > 0) freqs.add(f);
        if (freqs.size() < k) return 0;
        Collections.sort(freqs, Collections.reverseOrder());
        int cutoff = freqs.get(k - 1);
        long ans = 1;
        int strictlyGreater = 0, totalCutoff = 0;
        for (int f : freqs) {
            if (f > cutoff) {
                ans = (ans * f) % mod;
                strictlyGreater++;
            } else if (f == cutoff) {
                totalCutoff++;
            }
        }
        int needed = k - strictlyGreater;
        long ways = combination(totalCutoff, needed);
        ans = (ans * (ways % mod)) % mod;
        ans = (ans * power(cutoff, needed, mod)) % mod;
        return (int) ans;
    }
    private long combination(int n, int r) {
        if (r < 0 || r > n) return 0;
        long res = 1;
        for (int i = 1; i <= r; i++) res = res * (n - i + 1) / i;
        return res;
    }
    private long power(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}

/**
 * @param {string} s
 * @param {number} k
 * @return {number}
 */
var countKSubsequencesWithMaxBeauty = function(s, k) {
    const mod = 1000000007n;
    const cnt = new Array(26).fill(0);
    for (const c of s) cnt[c.charCodeAt(0) - 97]++;
    const freqs = cnt.filter(f => f > 0).sort((a, b) => b - a);
    if (freqs.length < k) return 0;
    const cutoff = freqs[k - 1];
    let ans = 1n;
    let strictlyGreater = 0, totalCutoff = 0;
    for (const f of freqs) {
        if (f > cutoff) {
            ans = (ans * BigInt(f)) % mod;
            strictlyGreater++;
        } else if (f === cutoff) {
            totalCutoff++;
        }
    }
    const needed = k - strictlyGreater;
    let ways = 1n;
    for (let i = 1; i <= needed; i++) {
        ways = ways * BigInt(totalCutoff - i + 1) / BigInt(i);
    }
    ans = (ans * (ways % mod)) % mod;
    let p = 1n, base = BigInt(cutoff);
    for (let i = 0; i < needed; i++) p = (p * base) % mod;
    ans = (ans * p) % mod;
    return Number(ans);
};
